update public.learning_paths
set
  title = 'Epistemology',
  goal = 'Epistemology',
  summary = 'The sequence begins with core concepts and skeptical pressure, then develops theories of justification, sources of knowledge, social knowledge, epistemic injustice, scientific inquiry, digital environments, and research writing.',
  data = $episjson${"slug": "epistemology", "title": "Epistemology", "description": "The sequence begins with core concepts and skeptical pressure, then develops theories of justification, sources of knowledge, social knowledge, epistemic injustice, scientific inquiry, digital environments, and research writing.", "topics": [{"id": "5f490f19-635b-42ab-8663-48dd53e07c73", "type": "topic", "title": "Epistemology as the Theory of Knowledge", "description": "Frame epistemology around knowledge, belief, truth, justification, rationality, evidence, inquiry, and intellectual responsibility.", "children": [{"id": "c5d0f665-2310-471c-bd95-e8463e2a54de", "type": "subtopic", "title": "Central questions", "children": [{"id": "f1cdcac6-3a02-4beb-a733-0e8ba326f7b9", "type": "concept", "title": "What is knowledge?"}, {"id": "b0718216-e9a9-4db8-ba73-9bfc715e4fa5", "type": "concept", "title": "What makes belief rational?"}, {"id": "afdd0bea-d215-4bff-82f0-ca94999689e8", "type": "concept", "title": "What counts as evidence?"}, {"id": "43adc7c7-8b87-4bee-a710-8b2b716bf3b4", "type": "concept", "title": "Why do error and disagreement matter?"}], "description": "Students begin by seeing epistemology as the study of how beliefs can be true, justified, rational, responsible, or knowledge."}, {"id": "464693f2-4188-4b42-aee9-4c4ca66e1b62", "type": "subtopic", "title": "Method in epistemology", "children": [{"id": "b00e922d-15d1-44d4-9642-0614de98afd2", "type": "concept", "title": "Conceptual analysis"}, {"id": "90ef8b0a-71c0-40ca-a086-a660b7b2a861", "type": "concept", "title": "Thought experiments"}, {"id": "fb115a1a-fb31-4eab-95bb-247a30eab2d8", "type": "concept", "title": "Counterexamples"}, {"id": "eb1537f3-3c4e-489c-bac5-68b92dd017a7", "type": "concept", "title": "Reflective equilibrium"}], "description": "The course uses argument analysis, cases, distinctions, and objections to clarify concepts."}, {"id": "bb8205b0-f402-41e6-9e3e-c6071452b8c5", "type": "subtopic", "title": "Epistemology in life", "children": [{"id": "ff26db66-20f6-4b25-b356-82848e079cbe", "type": "concept", "title": "Expert trust"}, {"id": "9501bbbe-4a4e-406f-afd5-8fc2f306eec8", "type": "concept", "title": "Public disagreement"}, {"id": "b607f4c7-05cc-49c9-a75e-5b0f82798e8d", "type": "concept", "title": "Misinformation"}, {"id": "e9040973-5c77-4f61-8873-34de5f0b09be", "type": "concept", "title": "Intellectual responsibility"}], "description": "The field matters because inquiry, science, law, politics, education, and digital life depend on norms of belief."}]}, {"id": "382a426b-4c24-4235-9160-b12eafa67d52", "type": "topic", "title": "Knowledge, Belief, Truth, and the Value of Knowing", "description": "Analyze what distinguishes knowledge from true belief and why knowledge matters.", "children": [{"id": "60a57302-1737-4046-9876-ae060cf2b0e3", "type": "subtopic", "title": "Traditional analysis", "children": [{"id": "f36c4024-0549-4df6-9d49-9c63923ec6ad", "type": "concept", "title": "Belief condition"}, {"id": "b869ec06-f759-48c4-8e29-3bb4bef2d938", "type": "concept", "title": "Truth condition"}, {"id": "13019a47-598e-48ea-b923-b7799800540b", "type": "concept", "title": "Justification condition"}, {"id": "3c555328-59b8-490a-a78b-b76637cac1a0", "type": "concept", "title": "Sufficiency and necessity"}], "description": "The justified true belief model gives students a baseline for later debates."}, {"id": "2e58b6fd-9506-4b6b-b39c-952e1864899e", "type": "subtopic", "title": "Truth and realism", "children": [{"id": "a4fb49e1-c93f-4104-99f2-cb133686719b", "type": "concept", "title": "Correspondence"}, {"id": "5007aea7-7969-4a48-9adf-51de7af6f748", "type": "concept", "title": "Coherence"}, {"id": "57730058-cb25-4592-8be9-cd20dbb2200d", "type": "concept", "title": "Pragmatic approaches"}, {"id": "99ad9e5c-6613-444f-8e79-d89a9f5f8c1c", "type": "concept", "title": "Realism and anti-realism"}], "description": "Knowledge requires truth, but philosophers dispute how truth should be understood."}, {"id": "d3ea1f43-23ba-455f-98d7-dd27bd124afb", "type": "subtopic", "title": "Value of knowledge", "children": [{"id": "1a03feb5-b472-4e72-8f11-86274ed6ddb3", "type": "concept", "title": "Meno problem"}, {"id": "dc2f3f7d-9330-420a-aa8e-12b943a7db46", "type": "concept", "title": "Practical success"}, {"id": "563c6567-240e-4609-893d-4abdb38d3230", "type": "concept", "title": "Understanding"}, {"id": "bb7478f7-6f4b-4aa0-942a-70d83b7fbc46", "type": "concept", "title": "Epistemic achievement"}], "description": "Students ask why knowledge is more valuable than lucky true belief."}]}, {"id": "1c6ecd6b-7637-482e-93c7-aead6f05f1fb", "type": "topic", "title": "The Gettier Problem and Post-Gettier Epistemology", "description": "Use Gettier cases to test traditional analyses of knowledge and motivate contemporary theories.", "children": [{"id": "24255411-326d-4e89-8d0c-7707f345f9c5", "type": "subtopic", "title": "Gettier cases", "children": [{"id": "c4ede446-c3a2-4844-a0e3-5dd8db2e89cf", "type": "concept", "title": "Luck"}, {"id": "748e3982-1a84-4d02-80a6-3cefdb0abec0", "type": "concept", "title": "False lemmas"}, {"id": "19544b1e-c2ed-4c6e-a1dc-24ffcb8a0ba1", "type": "concept", "title": "Coincidental truth"}, {"id": "75942e9c-c416-4a24-a77d-75bc9fec124a", "type": "concept", "title": "Counterexample method"}], "description": "Gettier examples show that justified true belief can still fall short of knowledge."}, {"id": "66b1fc16-5cf6-4afe-b589-4f16c1d4edce", "type": "subtopic", "title": "No-luck conditions", "children": [{"id": "4708e903-9181-4bce-9e7c-00c173de596a", "type": "concept", "title": "Sensitivity"}, {"id": "d7b27f5b-b485-4062-90b1-6498de23d9b4", "type": "concept", "title": "Safety"}, {"id": "36a32279-8f5e-4b52-9f14-ab05bdf751fe", "type": "concept", "title": "Defeasibility"}, {"id": "f3f904fa-cd8b-4737-a99a-e1cae1f1918c", "type": "concept", "title": "Causal connections"}], "description": "Post-Gettier theories try to exclude epistemic luck without becoming too strict."}, {"id": "2d6f74e1-c5f1-42fe-958f-2c655169032f", "type": "subtopic", "title": "Methodological lessons", "children": [{"id": "a5e419cb-d4dc-497e-a50b-604253bf8cac", "type": "concept", "title": "Case analysis"}, {"id": "6d8095da-6e76-4e1d-afa5-fbda7d2a776b", "type": "concept", "title": "Theory revision"}, {"id": "55c6853e-6f61-4700-9497-63d54101329e", "type": "concept", "title": "Intuition and its limits"}, {"id": "81996a6c-65f0-4d68-a6df-6fb101d902d2", "type": "concept", "title": "Philosophical progress"}], "description": "Students learn how a small case can reshape an entire theory."}]}, {"id": "0705da5e-dee9-48b0-852b-41ff0b445ff7", "type": "topic", "title": "Skepticism, Closure, and Responses to Radical Doubt", "description": "Study skeptical arguments and major strategies for resisting or living with them.", "children": [{"id": "1628c4de-9170-49f7-9191-1abc25c8ebf9", "type": "subtopic", "title": "Skeptical arguments", "children": [{"id": "568d9053-164d-4f84-9d25-dbc5f4dc47d7", "type": "concept", "title": "Dream argument"}, {"id": "d2ed9080-92d1-466a-8c23-3659a7b0c6f1", "type": "concept", "title": "Evil demon"}, {"id": "8f4e5aae-eac7-4342-baae-6d535bea9390", "type": "concept", "title": "Brain in a vat"}, {"id": "68092809-3656-4cbf-9a48-fc80134ad342", "type": "concept", "title": "Cartesian doubt"}], "description": "Skepticism pressures ordinary claims to knowledge by raising error possibilities."}, {"id": "c56034a7-5522-41b8-9240-93b372749ba3", "type": "subtopic", "title": "Closure and underdetermination", "children": [{"id": "8136a385-b34a-4689-ab3d-97ca8c7a9a5c", "type": "concept", "title": "Closure under known entailment"}, {"id": "aa7c2b1e-ae9a-4b2b-93db-1177baa50667", "type": "concept", "title": "Underdetermination"}, {"id": "81465900-a168-4bbb-8290-851a91c9d76e", "type": "concept", "title": "Tracking alternatives"}, {"id": "71415712-b8d5-4a26-9000-8c9504debeb0", "type": "concept", "title": "Relevant alternatives"}], "description": "These principles explain why skepticism can feel hard to escape."}, {"id": "ff9f558c-f0f4-4984-b04e-ec5b6c022aa4", "type": "subtopic", "title": "Responses to skepticism", "children": [{"id": "0f671ca6-abf7-4edc-a918-6a4159f7d3e2", "type": "concept", "title": "Moorean response"}, {"id": "fa656dbe-2572-4591-8c19-c7477c16d241", "type": "concept", "title": "Contextualism"}, {"id": "a0a5e51a-dbc0-48c7-ab84-65293139492b", "type": "concept", "title": "Externalist response"}, {"id": "2ca2802c-f5b1-481e-9fa7-34038897aeba", "type": "concept", "title": "Hinge epistemology"}], "description": "Students compare strategies for resisting, conceding, or reframing skeptical challenges."}]}, {"id": "ab400afe-e974-4660-9b8e-7e41dde205d2", "type": "topic", "title": "Foundationalism, Coherentism, and Infinitism", "description": "Compare structural theories of justification and the regress problems they answer.", "children": [{"id": "398fb4bb-0521-4dbc-84ba-6d9b0dcc48df", "type": "subtopic", "title": "Regress problem", "children": [{"id": "11545e19-eb20-47da-a7ad-868251f9faa1", "type": "concept", "title": "Infinite regress"}, {"id": "c03c60cd-6120-45ae-86d1-8ed714edebb2", "type": "concept", "title": "Circularity"}, {"id": "dbb060e1-400b-43db-b24b-d271ea72b45a", "type": "concept", "title": "Arbitrary stopping"}, {"id": "fb2bfc3a-da29-48ca-9453-9486dcb11159", "type": "concept", "title": "Epistemic support"}], "description": "The regress problem asks how chains of reasons can end, circle, or continue."}, {"id": "f2f4b63d-7227-4149-a4b8-3d3399081e44", "type": "subtopic", "title": "Foundationalism", "children": [{"id": "2fd67b7e-e73f-4a5e-b45e-4f0c6348e4fb", "type": "concept", "title": "Basic beliefs"}, {"id": "412fa7da-cd6c-4811-b6fc-a938276abe86", "type": "concept", "title": "Given and noninferential justification"}, {"id": "d62d0ac6-54c8-419c-b406-a8f064da4163", "type": "concept", "title": "Perceptual foundations"}, {"id": "f38d516a-083b-4153-9303-9ed86d41b5b6", "type": "concept", "title": "Classical and modest versions"}], "description": "Foundationalism claims some beliefs are justified without depending on other beliefs."}, {"id": "1538bef7-ae13-4000-9a74-0c556464d11d", "type": "subtopic", "title": "Coherentism and infinitism", "children": [{"id": "92e3b68e-a939-4e32-986d-d31902318e69", "type": "concept", "title": "Explanatory coherence"}, {"id": "ef4a2ebf-c05e-4ce7-8625-e23dfbeb665e", "type": "concept", "title": "Mutual support"}, {"id": "51169dc3-83bb-447a-b6a4-773fe804097b", "type": "concept", "title": "Linear chains"}, {"id": "ea756569-b6d0-4d00-8a62-7c2dd143bf12", "type": "concept", "title": "Objections and advantages"}], "description": "Alternative structures explain justification through networks or endless reasons."}]}, {"id": "5b9d17d5-9807-4563-a2d0-a297b11a11e0", "type": "topic", "title": "Internalism, Externalism, Reliabilism, and Proper Function", "description": "Examine whether justification depends on reflective access, reliable process, or cognitive design.", "children": [{"id": "f5e7c6ea-b654-41b3-b888-5e70a16af5d0", "type": "subtopic", "title": "Internalism", "children": [{"id": "158d2a5b-6543-4f08-9bb6-136520d4463b", "type": "concept", "title": "Access internalism"}, {"id": "b21db128-b0d6-4e8e-a5dc-2de35c4ef950", "type": "concept", "title": "Mentalism"}, {"id": "ccf0ff28-1c67-4b6f-a62f-b4b2fc4289ad", "type": "concept", "title": "Reasons and responsibility"}, {"id": "7f576689-db85-46c2-b894-0bf98ca02065", "type": "concept", "title": "New evil demon problem"}], "description": "Internalists emphasize what a subject can access or reflectively appreciate."}, {"id": "cdd2d6a3-7be1-4d5d-9f5c-ea6050e198ff", "type": "subtopic", "title": "Reliabilism", "children": [{"id": "3f539ee9-4300-434d-8f5c-4876114a670d", "type": "concept", "title": "Process reliability"}, {"id": "f0122149-78bc-4b1f-85c1-a0e6845204e8", "type": "concept", "title": "Perception and memory"}, {"id": "884cc6ce-d1f3-4959-8090-f324e8f54556", "type": "concept", "title": "Generality problem"}, {"id": "9704106b-c7ca-4a66-85a8-f6aff06c00ef", "type": "concept", "title": "Reliability versus reflection"}], "description": "Reliabilism links justification or knowledge to reliable belief-forming processes."}, {"id": "b963f2d6-1b6c-4539-b6e8-1df380bf8cf3", "type": "subtopic", "title": "Proper function", "children": [{"id": "0d29819d-2cb0-4437-b0af-b4d6f6ce89d2", "type": "concept", "title": "Design plan"}, {"id": "f5d71b9a-0e3c-44ef-af42-6460a0d70864", "type": "concept", "title": "Apt environment"}, {"id": "690ecaaf-d819-459b-9795-17db89b45350", "type": "concept", "title": "Warrant"}, {"id": "7e98ca43-c3f1-472a-9c01-f65f5f03939c", "type": "concept", "title": "Naturalized epistemology"}], "description": "Proper function accounts connect knowledge to cognitive design, environment, and successful functioning."}]}, {"id": "564c29d3-7513-489c-89a0-d54a4c5f0d96", "type": "topic", "title": "A Priori Knowledge, Rational Insight, and Analyticity", "description": "Investigate knowledge that seems independent of experience, including logic, mathematics, and conceptual truth.", "children": [{"id": "b978e429-bf01-4b2a-93fd-336abf6efe13", "type": "subtopic", "title": "A priori and a posteriori", "children": [{"id": "d796a820-a72a-4bc9-b45a-a17e3286ce3d", "type": "concept", "title": "Definitions"}, {"id": "4efb252c-63fe-4465-a7c6-04942e4f7876", "type": "concept", "title": "Mathematics"}, {"id": "147b438f-2dd7-4d1e-a802-ebce15909d47", "type": "concept", "title": "Logic"}, {"id": "a4a12216-8307-4095-83c5-7baae4398ee8", "type": "concept", "title": "Modal knowledge"}], "description": "Students learn to distinguish experience-based knowledge from knowledge apparently independent of experience."}, {"id": "46341f12-d5eb-4e49-8127-83f54dfc9c37", "type": "subtopic", "title": "Analyticity and necessity", "children": [{"id": "9c41def1-5fae-41d7-9a12-b40be154986c", "type": "concept", "title": "Analytic and synthetic"}, {"id": "5b0fe2fc-25b3-4ff9-9805-3aae8a1461a2", "type": "concept", "title": "Necessary and contingent"}, {"id": "65a8cf56-5268-4f5c-843b-dfbd27c0e0c3", "type": "concept", "title": "Kripkean complications"}, {"id": "30d35183-0e1b-4f52-90e5-43654d1369d2", "type": "concept", "title": "Conceptual truth"}], "description": "The topic connects language, concepts, and necessity."}, {"id": "3c459719-fef2-45e9-a836-7a398c654e96", "type": "subtopic", "title": "Kant and rational insight", "children": [{"id": "d35b3321-fd42-4267-a138-10da640c3870", "type": "concept", "title": "Synthetic a priori"}, {"id": "1308341b-17dc-428f-aa8a-1a23d65b74a5", "type": "concept", "title": "Conditions of experience"}, {"id": "b3730290-c614-4cdd-b2d6-1576aea69843", "type": "concept", "title": "Space and time"}, {"id": "7c02c627-bc05-4b63-9f6c-18ae91d6fd92", "type": "concept", "title": "Categories"}], "description": "Kant's synthetic a priori offers a historical and systematic challenge."}]}, {"id": "b1743a5f-7870-4177-ba6f-e33d2a022ddb", "type": "topic", "title": "Perception, Memory, and Introspection", "description": "Assess major sources of belief and their vulnerabilities to error, illusion, and self-deception.", "children": [{"id": "0e5661ed-1d17-45b5-a91c-99849fe1931a", "type": "subtopic", "title": "Perception", "children": [{"id": "c13d48ea-0e73-484d-8903-570153278c59", "type": "concept", "title": "Direct realism"}, {"id": "bc0f20be-675d-4e5d-a1ca-1409d6757de4", "type": "concept", "title": "Representationalism"}, {"id": "3490281d-454a-44f4-ab55-5f55ec4d425a", "type": "concept", "title": "Illusion"}, {"id": "c128faec-8ffe-44d4-8481-b5e35b47208b", "type": "concept", "title": "Hallucination"}], "description": "Perceptual knowledge is central because most empirical knowledge depends on the world appearing to us."}, {"id": "5eb2d5cf-7345-435f-86d0-509e11d582e3", "type": "subtopic", "title": "Memory", "children": [{"id": "e353f406-22ab-4381-b412-cba1097537d5", "type": "concept", "title": "Episodic memory"}, {"id": "95b66c25-2c74-4b2e-b102-33359a56f82a", "type": "concept", "title": "Semantic memory"}, {"id": "406f7b0b-f295-454a-b6d2-64aaf80423e1", "type": "concept", "title": "Memory reliability"}, {"id": "51fd4735-0444-4cfc-b76c-8a4ccd499c05", "type": "concept", "title": "Forgetting and distortion"}], "description": "Memory raises questions about preservation, reconstruction, and justification over time."}, {"id": "b1e9adc0-ed9b-4865-8a7b-40980af2d9b1", "type": "subtopic", "title": "Introspection", "children": [{"id": "e7a10c3a-0d08-4ce9-b27e-5fb10b7cf43a", "type": "concept", "title": "Mental states"}, {"id": "dfff4f76-539f-4de9-8350-3280c0063396", "type": "concept", "title": "Transparency"}, {"id": "a24e8ab2-4051-43e1-af57-99486c09f40d", "type": "concept", "title": "Self-deception"}, {"id": "d254b6fa-2dfa-4a6c-b7bb-8d15ff2f2493", "type": "concept", "title": "First-person authority"}], "description": "Self-knowledge can seem privileged, yet it is vulnerable to error."}]}, {"id": "8ac5e50a-35a6-4100-b406-baf26a1aa38c", "type": "topic", "title": "Induction, Probability, Evidence, and Bayesian Reasoning", "description": "Connect classical problems of induction to evidence, confirmation, probability, and rational belief update.", "children": [{"id": "1f65f9ab-046e-4c7b-862b-0f34a03af095", "type": "subtopic", "title": "Problem of induction", "children": [{"id": "3fe63da3-aa54-4a1e-93d0-4729c74a4003", "type": "concept", "title": "Uniformity of nature"}, {"id": "2cfee203-de8c-4ffe-9cd6-52e6178de49f", "type": "concept", "title": "Circular justification"}, {"id": "62f2ee8b-fea0-4b23-b7ab-458ba6352430", "type": "concept", "title": "Causation"}, {"id": "71d04abb-974b-418a-97d5-7a1fa1c14968", "type": "concept", "title": "Naturalized response"}], "description": "Hume's problem asks why past regularities justify expectations about the future."}, {"id": "4b98f49a-e79e-4be5-a6fa-59a1ae1a2337", "type": "subtopic", "title": "Confirmation and evidence", "children": [{"id": "e0d9dff7-505b-4e18-b904-6cdad2701e89", "type": "concept", "title": "Hypothesis testing"}, {"id": "27754c04-b3a5-4720-91e2-601d9b52e2e0", "type": "concept", "title": "Confirmation"}, {"id": "76d88663-5d30-4238-ad50-4de0473c92ef", "type": "concept", "title": "Underdetermination"}, {"id": "34cf5718-7bf4-4c93-b7b1-18159d7981ee", "type": "concept", "title": "Inference to the best explanation"}], "description": "Students examine what it means for evidence to support a hypothesis."}, {"id": "26c72416-75fc-484e-a817-06d3b6358e14", "type": "subtopic", "title": "Bayesian reasoning", "children": [{"id": "18a453b1-4708-498a-8cce-36b5ebd1b252", "type": "concept", "title": "Priors"}, {"id": "da23865a-9098-42d3-9183-84bb10922a2c", "type": "concept", "title": "Likelihoods"}, {"id": "6747a25a-5455-4ec5-be65-0294cb07c245", "type": "concept", "title": "Posterior probability"}, {"id": "dd34b780-a028-42f6-b46e-99df0135b22b", "type": "concept", "title": "Base-rate neglect"}], "description": "Bayesian tools clarify rational updating and the role of prior belief."}]}, {"id": "5f652b80-7c3b-4d67-9d67-2427dcb06bb3", "type": "topic", "title": "Testimony, Trust, Experts, and Disagreement", "description": "Study how knowledge depends on other people, institutions, expertise, and disagreement.", "children": [{"id": "da025707-27ac-493b-810c-41180dd437eb", "type": "subtopic", "title": "Testimony", "children": [{"id": "b3998ab2-8aa4-416a-8649-aea334b27254", "type": "concept", "title": "Reductionism"}, {"id": "754a13dc-6e2c-45d1-8d4c-517743d09ec7", "type": "concept", "title": "Anti-reductionism"}, {"id": "41e4a644-a8da-471d-aa4e-bbedb9a32d3d", "type": "concept", "title": "Speaker reliability"}, {"id": "87a7bd78-9b4c-4227-8bb3-ebf9669e39a4", "type": "concept", "title": "Hearer responsibility"}], "description": "Much of what we know depends on others, so testimony is not a marginal source."}, {"id": "429b9ba9-ae22-4930-b1e2-36e556afc747", "type": "subtopic", "title": "Expertise", "children": [{"id": "2d096d85-2278-41d6-b391-ec2943c0ddf7", "type": "concept", "title": "Credentials"}, {"