oup belief"}, {"id": "91688717-d0bd-4f62-9c78-8a51ae7e41b6", "type": "concept", "title": "Collective evidence"}, {"id": "80748977-51b9-4569-85ee-993f44d23e67", "type": "concept", "title": "Distributed cognition"}, {"id": "24c5cc5f-4ad8-4f30-98a3-91de8ab9af67", "type": "concept", "title": "Organizational ignorance"}], "description": "Students ask whether groups can believe, know, or be responsible."}, {"id": "310c72e2-ea59-4c17-a64f-7be6d2e274aa", "type": "subtopic", "title": "Information environments", "children": [{"id": "ee65b91d-6de8-437d-a21b-906e843fe653", "type": "concept", "title": "Media systems"}, {"id": "00913018-2fa2-4980-8764-02d9d0da834a", "type": "concept", "title": "Echo chambers"}, {"id": "87036072-0c0c-4119-aa77-c07f0edcfd85", "type": "concept", "title": "Epistemic bubbles"}, {"id": "8d9275a2-c836-480d-9f9f-17cb758da5a7", "type": "concept", "title": "Public knowledge"}], "description": "Social structures affect which beliefs spread and which evidence becomes visible."}]}, {"id": "c6d6c07b-5a06-4d59-8d54-0f674abccc7b", "type": "topic", "title": "Epistemic Injustice, Standpoint, and Power", "description": "Analyze how social power can distort credibility, interpretation, participation, and access to knowledge.", "children": [{"id": "263f20c3-c0cc-4246-a6cc-715a44793a86", "type": "subtopic", "title": "Testimonial injustice", "children": [{"id": "f0d9e902-2552-49f8-9aa2-4db4762c9829", "type": "concept", "title": "Credibility deficit"}, {"id": "304b2baa-41ec-4227-b509-6af8ba075a37", "type": "concept", "title": "Credibility excess"}, {"id": "c54e89eb-4846-4a94-b8ec-049f7a34e725", "type": "concept", "title": "Prejudice"}, {"id": "2170a867-c49b-4a9c-9b25-73de8b04e63c", "type": "concept", "title": "Speaker silencing"}], "description": "Students analyze how credibility can be unfairly inflated or deflated."}, {"id": "93f4926e-419f-471a-8ffd-6e0c896990a1", "type": "subtopic", "title": "Hermeneutical injustice", "children": [{"id": "f0dc6af0-697d-4f25-a961-e0557885ebce", "type": "concept", "title": "Interpretive gaps"}, {"id": "5a6fa530-8034-4224-b08d-f582e24b0617", "type": "concept", "title": "Marginalization"}, {"id": "ee1f245f-45a0-4aba-8d97-c855dd460962", "type": "concept", "title": "Concept creation"}, {"id": "370bc9e0-c561-43a6-860c-928eb0aea2c8", "type": "concept", "title": "Social uptake"}], "description": "Some experiences become hard to understand because shared interpretive resources are missing."}, {"id": "e3170df0-b57d-492d-a164-47d735bea823", "type": "subtopic", "title": "Standpoint and situated knowledge", "children": [{"id": "34221cb9-3c2d-4397-9173-f2b5374c2e0a", "type": "concept", "title": "Standpoint epistemology"}, {"id": "a499f91c-1eaf-4f84-b1e3-bc3df7e6c63b", "type": "concept", "title": "Strong objectivity"}, {"id": "4c7ee5fa-9954-4b6d-8ac6-614d55efea73", "type": "concept", "title": "Experience and evidence"}, {"id": "823c2fe1-6a64-4b67-81fa-b132d152d4c0", "type": "concept", "title": "Power and ignorance"}], "description": "The course connects social position to evidence, inquiry, and objectivity."}]}, {"id": "1d45c64c-5771-4ffc-bc6b-682127adc9ac", "type": "topic", "title": "Virtue Epistemology, Intellectual Character, and Inquiry", "description": "Connect knowledge to intellectual virtues, vices, responsibility, curiosity, humility, and courage.", "children": [{"id": "78e7dd73-121e-4b54-b622-bc71950569a6", "type": "subtopic", "title": "Epistemic virtues", "children": [{"id": "dd197205-c0ad-47c6-aa3c-c3f9ee3c3883", "type": "concept", "title": "Open-mindedness"}, {"id": "913fd80f-2c6d-4329-adeb-b5533f444198", "type": "concept", "title": "Intellectual humility"}, {"id": "01a0f129-7e20-4383-a61a-edc18569785b", "type": "concept", "title": "Courage"}, {"id": "8f1f606f-b6d7-429f-8417-2d7c013f7d22", "type": "concept", "title": "Carefulness"}], "description": "Virtue epistemology focuses on the character traits and abilities of good inquirers."}, {"id": "fca28653-069a-4351-82b0-d0b10fbebcef", "type": "subtopic", "title": "Epistemic vices", "children": [{"id": "32487748-f5b5-4406-bd15-fa640866d4cf", "type": "concept", "title": "Dogmatism"}, {"id": "4c43bae4-0a2f-40ef-968b-7fd0cf57d8a2", "type": "concept", "title": "Closed-mindedness"}, {"id": "ad342ada-903c-4bde-b50a-612182e092b7", "type": "concept", "title": "Arrogance"}, {"id": "bcd7198d-e867-4f2b-b0d9-e9a0473b9f15", "type": "concept", "title": "Wishful thinking"}], "description": "Students examine how character flaws and habits damage inquiry."}, {"id": "cd77e8f3-bdb2-41ef-bf6e-29cc9c575232", "type": "subtopic", "title": "Credit and achievement", "children": [{"id": "b19de977-30df-475d-a2c7-10e53e035d38", "type": "concept", "title": "Apt belief"}, {"id": "d248a0b9-6fdd-48df-b044-0b0453a6b969", "type": "concept", "title": "Skill"}, {"id": "a7cce93f-8050-40e0-a932-8d18a49d36ae", "type": "concept", "title": "Credit"}, {"id": "9c8b0b39-293e-41f1-ae6e-a6a69d69bb34", "type": "concept", "title": "Responsibility"}], "description": "Some theories explain knowledge as a kind of successful cognitive achievement."}]}, {"id": "9cc65585-90f6-4058-b809-9b06c493b2a4", "type": "topic", "title": "Epistemology of Science, Models, and Explanation", "description": "Apply epistemological tools to scientific evidence, models, idealization, realism, and values in inquiry.", "children": [{"id": "4f8cb7cc-6b13-465b-ae49-8e5ef60632a0", "type": "subtopic", "title": "Scientific evidence", "children": [{"id": "f882da31-bf0c-444e-aadb-c523c43228cf", "type": "concept", "title": "Observation"}, {"id": "fa23a604-6fb9-4464-87a0-c04b91813288", "type": "concept", "title": "Experiment"}, {"id": "d5ac380a-8ef3-4d35-a116-f675dbdc5d48", "type": "concept", "title": "Replication"}, {"id": "53576ce3-1871-4ac3-90d4-8da33281ca60", "type": "concept", "title": "Measurement error"}], "description": "Science raises special questions about observation, experiment, measurement, and theory."}, {"id": "e0aefadd-c655-475e-bc86-ddcec50869c8", "type": "subtopic", "title": 