ormation", "children": [{"id": "d042b519-ff67-4a21-a26d-650faa4f18f2", "type": "concept", "title": "Disinformation"}, {"id": "a59ed1ab-e446-423c-b617-f7d89257030a", "type": "concept", "title": "Misinformation"}, {"id": "f7f36880-9b5f-4e8d-bf18-95749f96ba3a", "type": "concept", "title": "Conspiracy theories"}, {"id": "a98989a5-cc0f-4003-b781-98d69c8f1841", "type": "concept", "title": "Correction and backfire effects"}], "description": "Students apply epistemology to false belief formation at scale."}, {"id": "a1353c18-0924-48f6-bfa8-01e8f77c826f", "type": "subtopic", "title": "AI and algorithms", "children": [{"id": "e16aebf8-4796-4c7c-9f69-e181ff8e14a9", "type": "concept", "title": "Algorithmic authority"}, {"id": "24016078-c4dc-4349-aa2d-1982d14bd5ba", "type": "concept", "title": "Explainability"}, {"id": "56817d12-ad1f-4a0b-bcb3-476ee9ba8961", "type": "concept", "title": "Hallucination"}, {"id": "3e055891-d8ac-4916-a0b5-81445cc0df5e", "type": "concept", "title": "Human oversight"}], "description": "AI systems create new questions about testimony, opacity, and epistemic dependence."}]}, {"id": "627587da-1957-4855-a637-26e3255e828f", "type": "topic", "title": "Capstone Research Paper on Justification and Knowledge", "description": "Develop a rigorous philosophical research paper with argument reconstruction, objection, reply, and scholarly sources.", "children": [{"id": "03584df8-d634-497e-9fa3-a07b4f8fd620", "type": "subtopic", "title": "Research question", "children": [{"id": "b771c9c3-019b-4482-bfec-d389d8c3c84a", "type": "concept", "title": "Topic narrowing"}, {"id": "9da2e9fe-98ec-4c39-8123-e16a29eafb38", "type": "concept", "title": "Thesis formation"}, {"id": "ead228ae-b3a3-4fd5-a9b0-39b186b54e8c", "type": "concept", "title": "Literature search"}, {"id": "a759926d-2a36-4f73-a26b-e75082d98fa2", "type": "concept", "title": "Argument map"}], "description": "A strong paper begins with a focused question that matters to a live debate."}, {"id": "91617475-720e-42f0-